export type PrismaPromise<T> = $Public.PrismaPromise<T>


/**
 * Model User
 * Usuarios del sistema (administradores, asesores)
 * Autenticación delegada a Firebase Auth
 */
export type User = $Result.DefaultSelection<Prisma.$UserPayload>
/**
 * Model Client
 * Clientes activos del sistema.
 * Solo clientes que han sido convertidos de prospectos y tienen pólizas o potencial de negocio.
 */
export type Client = $Result.DefaultSelection<Prisma.$ClientPayload>
/**
 * Model Prospect
 * Prospectos (leads) que aún no se han convertido en clientes.
 * Se gestionan en el pipeline de ventas hasta su conversión o descarte.
 */
export type Prospect = $Result.DefaultSelection<Prisma.$ProspectPayload>
/**
 * Model ClientTag
 * Tags normalizados para clientes (etiquetas personalizables)
 */
export type ClientTag = $Result.DefaultSelection<Prisma.$ClientTagPayload>
/**
 * Model ProspectService
 * Tabla pivote: servicios de interés de cada prospecto
 */
export type ProspectService = $Result.DefaultSelection<Prisma.$ProspectServicePayload>
/**
 * Model ServiceCategory
 * Categorías principales de servicios (Seguros, Asesorías, Servicios Adicionales)
 */
export type ServiceCategory = $Result.DefaultSelection<Prisma.$ServiceCategoryPayload>
/**
 * Model ServiceSubcategory
 * Subcategorías de servicios (Movilidad, Salud, Vida, Legal, SST)
 */
export type ServiceSubcategory = $Result.DefaultSelection<Prisma.$ServiceSubcategoryPayload>
/**
 * Model Service
 * Catálogo de servicios ofrecidos (Seguro Todo Riesgo, Asesoría Legal, etc.)
 */
export type Service = $Result.DefaultSelection<Prisma.$ServicePayload>
/**
 * Model ClientService
 * Tabla pivote: servicios de interés de cada prospecto/cliente
 */
export type ClientService = $Result.DefaultSelection<Prisma.$ClientServicePayload>
/**
 * Model Policy
 * Pólizas emitidas a clientes
 */
export type Policy = $Result.DefaultSelection<Prisma.$PolicyPayload>
/**
 * Model Invoice
 * Facturas electrónicas emitidas
 */
export type Invoice = $Result.DefaultSelection<Prisma.$InvoicePayload>
/**
 * Model InvoiceItem
 * Ítems individuales dentro de una factura
 */
export type InvoiceItem = $Result.DefaultSelection<Prisma.$InvoiceItemPayload>
/**
 * Model InvoiceVerification
 * Token de verificación pública para facturas (QR)
 */
export type InvoiceVerification = $Result.DefaultSelection<Prisma.$InvoiceVerificationPayload>
/**
 * Model PaymentRequest
 * Cuentas de cobro emitidas a clientes (similares a facturas pero sin requisitos DIAN)
 */
export type PaymentRequest = $Result.DefaultSelection<Prisma.$PaymentRequestPayload>
/**
 * Model PaymentRequestItem
 * Ítems individuales dentro de una cuenta de cobro
 */
export type PaymentRequestItem = $Result.DefaultSelection<Prisma.$PaymentRequestItemPayload>
/**
 * Model Reminder
 * Recordatorios y alertas preventivas (renovaciones, seguimientos, etc.)
 */
export type Reminder = $Result.DefaultSelection<Prisma.$ReminderPayload>
/**
 * Model Goal
 * Metas de negocio con seguimiento de progreso
 */
export type Goal = $Result.DefaultSelection<Prisma.$GoalPayload>
/**
 * Model GoalMilestone
 * Hitos intermedios de una meta
 */
export type GoalMilestone = $Result.DefaultSelection<Prisma.$GoalMilestonePayload>
/**
 * Model TelegramConnection
 * Conexiones de usuarios CRM con cuentas de Telegram
 * Relación 1:1 — un usuario puede tener un solo Telegram vinculado
 */
export type TelegramConnection = $Result.DefaultSelection<Prisma.$TelegramConnectionPayload>
/**
 * Model TelegramVerificationCode
 * Códigos de verificación para vincular cuenta de Telegram con CRM
 */
export type TelegramVerificationCode = $Result.DefaultSelection<Prisma.$TelegramVerificationCodePayload>
/**
 * Model ActivityLog
 * Registro de actividad reciente del sistema (feed del dashboard)
 */
export type ActivityLog = $Result.DefaultSelection<Prisma.$ActivityLogPayload>

